// === Tab: mySketch ===
 // by SamuelYAN
 // more works //
 // https://twitter.com/SamuelAnn0924
 // https://www.instagram.com/samuel_yan_1990/

 // learn from https://p5js.org/examples/arrays-array-objects.html


 var ranges;
 let seed = Math.random() * 1247;
 var mySize, margin, grad;
 let str_wei = 0;

 // colors
 let colors0 = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
 let colorbg;

 let unit_x, unit_y;
 let count;
 let stop_count = 0;
 let t = 0;
 let mods = [];

 function setup() {
 	randomSeed(seed);
 	mySize = max(windowWidth, windowHeight);
 	createCanvas(mySize, mySize);
	 colorMode(RGB,100);
 	colorbg = random(colors0);
 	background(colorbg);
 	t = rez = c = n = 0.01;
 	xOff = 0;
 	yOff = 0;
 }

 function draw() {
 	randomSeed(seed);
 	background(colorbg);
 	let plus = 10;
 	for (let i = xOff; i < width - xOff; i += plus) {
 		for (let j = yOff; j < height - yOff; j += plus) {
 			strokeWeight(random(0.1));
 			var n = noise(i * rez+t, j * rez +t);
 			stroke(n * 255, n * 255, n * 255, n*100);
 			fill(n * 255, n * 255, n * 255, n*100);

 			push();
 			translate(i, j);
 			ellipse(0, 0, plus*n, n*plus);
 			pop();
 		}
 	}
 	t += 0.01;
 	rez += 0.00001;
 }

 function keyTyped() {
 	if (key === "s" || key === "S") {
 		saveCanvas("2D Noise", "png");
 	}
 }

